     * @param xpath The XPath expression to convert.
     * @param driver The WebDriver instance.
     * @return A UI Selector (By.XPATH) representing the XPath expression, or null if the element is not found.
     */
    public static By getUISelectorFromXPath(String xpath, WebDriver driver) {
        try {
            WebElement element = driver.findElement(By.xpath(xpath));
            return By.xpath(xpath);
        } catch (Exception e) {
            System.err.println("XPath '" + xpath + "' not found: " + e.getMessage());
            return null;
        }
    }

